/* Dirty-page false positives must never hide a changed byte or read beyond
 * the mapped allocation. Generated bytes only; no guest data required. */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/mman.h>
#include <unistd.h>
#include "hw/xbox/nv2a/pgraph/vk/vertex-upload.h"

int main(void)
{
    size_t page = (size_t)sysconf(_SC_PAGESIZE);
    size_t capacity = VK_VERTEX_UPLOAD_COMPARE_LIMIT;
    assert(page && capacity % page == 0);
    unsigned char *mapped = mmap(NULL, capacity + page,
        PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    unsigned char *incoming = mmap(NULL, capacity + page,
        PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    assert(mapped != MAP_FAILED && incoming != MAP_FAILED);
    assert(mprotect(mapped + capacity, page, PROT_NONE) == 0);
    assert(mprotect(incoming + capacity, page, PROT_NONE) == 0);
    for (size_t i = 0; i < capacity; i++) {
        mapped[i] = incoming[i] = (unsigned char)(i * 73 + (i >> 8) * 19);
    }
    assert(vk_vertex_upload_unchanged(mapped, capacity, incoming,
                                      0, capacity, true));
    /* Exercise every byte, including page boundaries and the final byte. */
    for (size_t i = 0; i < capacity; i++) {
        incoming[i] ^= 1;
        assert(!vk_vertex_upload_unchanged(mapped, capacity, incoming,
                                           0, capacity, true));
        incoming[i] ^= 1;
    }
    for (size_t size = 1; size <= capacity; size *= 2) {
        size_t offset = capacity - size;
        assert(vk_vertex_upload_unchanged(mapped, capacity, incoming + offset,
                                          offset, size, true));
    }
    assert(vk_vertex_upload_unchanged(mapped, capacity, incoming + 3,
                                      3, 4093, true));
    /* Make both allocations read-only: the helper must not rewrite equal
     * data, including when callers have queued GPU reads of these bytes. */
    assert(mprotect(mapped, capacity, PROT_READ) == 0);
    assert(mprotect(incoming, capacity, PROT_READ) == 0);
    for (unsigned i = 0; i < 64; i++) {
        assert(vk_vertex_upload_unchanged(mapped, capacity, incoming,
                                          0, capacity, true));
    }
    const void *unreadable = incoming + capacity;
    assert(!vk_vertex_upload_unchanged(mapped, capacity, unreadable, 0, 1, false));
    assert(!vk_vertex_upload_unchanged(unreadable, capacity, unreadable,
                                       0, capacity + 1, true));
    assert(!vk_vertex_upload_unchanged(mapped, capacity, unreadable,
                                       capacity, 1, true));
    assert(!vk_vertex_upload_unchanged(mapped, capacity, unreadable,
                                       UINT64_MAX, 1, true));
    assert(!vk_vertex_upload_unchanged(mapped, capacity, unreadable,
                                       0, UINT64_MAX, true));
    assert(!vk_vertex_upload_unchanged(mapped, capacity, unreadable, 0, 0, true));
    assert(!vk_vertex_upload_unchanged(NULL, capacity, incoming, 0, 1, true));
    assert(!vk_vertex_upload_unchanged(mapped, capacity, NULL, 0, 1, true));
    assert(munmap(mapped, capacity + page) == 0);
    assert(munmap(incoming, capacity + page) == 0);
    puts("PASS exact vertex comparisons, changed-byte detection and guarded bounds");
    return 0;
}
